@CrossOrigin
@RestController
@RequestMapping("/AnomalyQuery")
public class AnomalyQueryRestController extends BaseSpringRestController {
	
	public AnomalyQueryRestController( AnomalyService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Anomaly using a UUID
     * @param		UUID anomalyId
     * @return		Anomaly
     */    
    @GetMapping("/load")
    public Anomaly load( @RequestParam(required=true) UUID anomalyId ) {
    	Anomaly entity = null;

    	try {  
    		entity = service.getAnomaly( new AnomalyFetchOneSummary( anomalyId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Anomaly using Id " + anomalyId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Anomaly business objects
     * @return		Set<Anomaly>
     */
    @GetMapping("/")
    public List<Anomaly> loadAll() {                
    	List<Anomaly> anomalyList = null;
        
    	try {
            // load the Anomaly
            anomalyList = service.getAllAnomaly();
            
            if ( anomalyList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Anomalys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Anomalys ", exc );
        	return null;
        }

        return anomalyList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Anomaly anomaly = null;
    protected AnomalyService service = null;
    private static final Logger LOGGER = Logger.getLogger(AnomalyQueryRestController.class.getName());
    
}
